fn write_new_hex_key(path: &str, bytes: &[u8], secret: bool) -> Result<()> {
    let encoded = key_encoding::encode_key_file(bytes)
        .ok_or_else(|| "key file encoding is too large".to_owned())?;
    write_new_file(path, encoded.as_bytes(), secret)
}

